function nearestTarget(){let best=null,dist=2;for(const d of doors){if(!d.opened){let z=Math.hypot(player.x-(d.x+.5),player.y-(d.y+.5));if(z<dist){best={kind:'door',item:d,distance:z};dist=z}}}for(const o of objects){if(o.taken||o.boarded||o.active)continue;let z=Math.hypot(player.x-(o.x+.5),player.y-(o.y+.5));if(z<dist){best={kind:o.type,item:o,distance:z};dist=z}}if(defend>0&&defend<=60&&objects[4].called){let o=objects[4],z=Math.hypot(player.x-(o.x+.5),player.y-(o.y+.5));if(z<2.1)best={kind:'board',item:o,distance:z}}return best}
function interact(){const target=nearestTarget();if(!target)return;const {kind,item}=target;if(kind==='door'){if(item.need>have.filter(Boolean).length){message(tx('needCard'));return}item.opened=true;world[item.y][item.x]=0;message((lang==='de'?'SICHERHEITSTOR ENTRIEGELT':'SECURITY GATE UNLOCKED'));if(item.need===0)radio('“You have the light. The access card is in Medical. Keep moving.”');if(item.need===1)radio('“Labs are open. I can hear it moving in the walls.”');if(item.need===2)radio('“Reactor access granted. Bring the generator online.”');return}if(kind==='card'){item.taken=true;have[item.id-1]=true;message(tx('gotCard')+' · '+item.id);radio(item.id===1?'“Medical card confirmed. The lab route should be open now.”':item.id===2?'“Lab key accepted. Reactor access is yours.”':'“All sector keys are accounted for. Restore the main generator.”');updateObjective();return}if(kind==='generator'){if(have.filter(Boolean).length<3){message(tx('needCard'));return}item.active=true;message('GENERATOR ONLINE · EMERGENCY POWER RESTORED');objects[4].called=false;updateObjective();radio('“Power is back. The surface lift is responding. Get there now.”');return}if(kind==='elevator'){if(!objects[3].active){message(tx('needPower'));return}if(!item.called){item.called=true;defend=60;message('ELEVATOR CALLED · 60:00');updateObjective();radio('“Lift is on its way. Hold the position. It heard the alarm.”');return}if(defend<=0){item.boarded=true;endGame(true)}}}
function shareBattery(){if(!started)return;if(bots.length){player.battery=Math.max(0,player.battery-20);message(tx('battery'))}else message(lang==='de'?'KEIN TEAMMATE IN REICHWEITE':'NO TEAMMATE IN RANGE')}
function reviveBot(){if(!bots.length){message(lang==='de'?'NIEMAND ZU BELEBEN':'NO ONE TO REVIVE');return}message(tx('revive'))}
$('#journal-close').onclick=()=>toggleJournal();addEventListener('keydown',e=>{if(e.code==='Escape'&&started&&journal.classList.contains('hidden')){document.exitPointerLock?.();paused=true}});
