let zbuf=[];const clamp=(v,a,b)=>Math.max(a,Math.min(b,v));function cell(x,y){if(x<0||y<0||x>=MW||y>=MH)return 1;return world[y][x]}
function castRay(angle){let dx=Math.cos(angle),dy=Math.sin(angle),mx=Math.floor(player.x),my=Math.floor(player.y),ddx=Math.abs(1/(dx||.00001)),ddy=Math.abs(1/(dy||.00001)),sx=dx<0?-1:1,sy=dy<0?-1:1,sdx=(dx<0?player.x-mx:mx+1-player.x)*ddx,sdy=(dy<0?player.y-my:my+1-player.y)*ddy,side=0,t=0;for(let i=0;i<60;i++){if(sdx<sdy){sdx+=ddx;mx+=sx;side=0}else{sdy+=ddy;my+=sy;side=1}let c=cell(mx,my);if(c){t=side===0?(mx-player.x+(1-sx)/2)/(dx||.0001):(my-player.y+(1-sy)/2)/(dy||.0001);return{dist:Math.max(.05,t),side,mx,my,tile:c,dx,dy}}}return{dist:30,side:0,mx,my,tile:1,dx,dy}}
function wallColor(hit,u){let tile=hit.tile,base=tile===2?[100,82,57]:hit.my%7===0?[67,72,68]:[56,61,57];let lum=1/(1+hit.dist*.21);if(hit.side)lum*=.78;let stripe=Math.sin(u*48)*.04+Math.sin(hit.my*8.2+hit.mx*3)*.035;let crack=((Math.sin(u*13+hit.my*9)*Math.cos(u*31+hit.mx*8))>.94)?.48:1;let flicker=1;if(hit.my<10&&hit.mx>10&&hit.mx<19)flicker=.9+.1*Math.sin(elapsed*8);let r=base[0]*lum*crack*flicker*(1+stripe),g=base[1]*lum*crack*flicker*(1+stripe),b=base[2]*lum*crack*flicker*(1+stripe);if(flashlight){const a=Math.atan2(hit.my+.5-player.y,hit.mx+.5-player.x),delta=Math.abs(Math.atan2(Math.sin(a-player.a),Math.cos(a-player.a)));let beam=Math.max(0,1-delta/.56)*Math.max(0,1-hit.dist/9);let pulse=player.battery<18?.75+.25*Math.sin(elapsed*19):1;r+=beam*135*pulse;g+=beam*139*pulse;b+=beam*130*pulse}if(hit.my>12&&hit.mx>25){r+=Math.max(0,1-hit.dist/5)*65}return`rgb(${clamp(r,0,255)|0},${clamp(g,0,255)|0},${clamp(b,0,255)|0})`}
function drawScene(dt){if(!W||!H)return;ctx.fillStyle='#080b0c';ctx.fillRect(0,0,W,H);const horizon=H*.49+Math.sin(elapsed*1.6)*2;let grad=ctx.createLinearGradient(0,0,0,H);grad.addColorStop(0,'#090d0d');grad.addColorStop(.48,'#111414');grad.addColorStop(.49,'#242622');grad.addColorStop(1,'#080a09');ctx.fillStyle=grad;ctx.fillRect(0,0,W,H);const cols=Math.min(Math.ceil(W/2),800),cw=W/cols,fov=Math.PI*.36;zbuf.length=cols;
for(let i=0;i<cols;i++){let rayA=player.a-fov/2+(i/cols)*fov,hit=castRay(rayA),dist=hit.dist*Math.cos(rayA-player.a);zbuf[i]=dist;let wh=Math.min(H*2,H/(dist*.75)),top=horizon-wh*.5;let u=hit.side===0?player.y+hit.dist*hit.dy:player.x+hit.dist*hit.dx;u-=Math.floor(u);ctx.fillStyle=wallColor(hit,u);ctx.fillRect(i*cw,top,cw+1,wh);if(u<.045||u>.955){ctx.fillStyle='rgba(8,9,8,.35)';ctx.fillRect(i*cw,top,cw+1,wh)}if(hit.tile===2){ctx.fillStyle='rgba(190,138,76,.25)';ctx.fillRect(i*cw,top+wh*.1,cw+1,Math.max(1,wh*.04))}}
// Floor tile seams recede into the black and pick up flashlight spill.
for(let n=0;n<11;n++){let p=(n+1)/12,y=horizon+Math.pow(p,1.8)*(H-horizon),alpha=(1-p)*.1;ctx.strokeStyle=`rgba(166,169,149,${alpha})`;ctx.lineWidth=1;ctx.beginPath();ctx.moveTo(0,y);ctx.lineTo(W,y);ctx.stroke()}for(let n=-8;n<=8;n++){ctx.strokeStyle='rgba(150,153,139,.045)';ctx.beginPath();ctx.moveTo(W/2+n*5,horizon);ctx.lineTo(W/2+n*W*.15,H);ctx.stroke()}

